TLM.f("Sancti/04-30",{"officium":"S. Catharina Senensis Virgine","rule":["vide C6b;","Gloria"],"ruleInherited":["Prefatio=Virginis"],"fallback":"Commune/C6b","from":{"Introitus":"Commune/C6b","Lectio":"Commune/C6b","Graduale":"Commune/C6b","GradualeP":"Commune/C6b","Tractus":"Commune/C6b","Evangelium":"Commune/C6b","Offertorium":"Commune/C6b","Communio":"Commune/C6b"},"sections":{"Introitus":[{"k":"ref","la":"Ps 44:8"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Da, quǽsumus, omnípotens Deus: ut, qui beátæ Catharínæ Vírginis tuæ natalítia cólimus; et ánnua solemnitáte lætámur, et tantæ virtútis proficiámus exémplo."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"2 Cor 10:17-18; 11:1-2"},{"k":"text","la":"Fratres: Qui gloriátur, in Dómino gloriétur. Non enim, qui seípsum comméndat, ille probátus est; sed quem Deus comméndat. Utinam sustinerétis módicum quid insipiéntiæ meæ, sed et supportáte me: æmulor enim vos Dei æmulatióne. Despóndi enim vos uni viro vírginem castam exhibére Christo."}],"Graduale":[{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua.","mark":"V"},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Audi, fília, et vide, et inclína aurem tuam: quia concupívit Rex spéciem tuam."},{"k":"ref","la":"Ps 44:13; 44:10"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: fíliæ regum in honóre tuo."},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi."},{"k":"text","la":"Afferéntur in lætítia et exsultatióne: adducéntur in templum Regis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 25:1-13"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile erit regnum coelórum decem virgínibus: quæ, accipiéntes lámpades suas, exiérunt óbviam sponso et sponsæ. Quinque autem ex eis erant fátuæ, et quinque prudéntes: sed quinque fátuæ, accéptis lampádibus, non sumpsérunt óleum secum: prudéntes vero accepérunt óleum in vasis suis cum lampádibus. Moram autem faciénte sponso, dormitavérunt omnes et dormiérunt. Média autem nocte clamor factus est: Ecce, sponsus venit, exíte óbviam ei. Tunc surrexérunt omnes vírgines illae, et ornavérunt lámpades suas. Fátuæ autem sapiéntibus dixérunt: Date nobis de óleo vestro: quia lámpades nostræ exstinguúntur. Respondérunt prudéntes, dicéntes: Ne forte non suffíciat nobis et vobis, ite pótius ad vendéntes, et émite vobis. Dum autem irent émere, venit sponsus: et quæ parátæ erant, intravérunt cum eo ad núptias, et clausa est jánua. Novíssime vero véniunt et réliquæ vírgines, dicéntes: Dómine, Dómine, áperi nobis. At ille respóndens, ait: Amen, dico vobis, néscio vos. Vigiláte ítaque, quia nescítis diem neque horam."}],"Offertorium":[{"k":"ref","la":"Ps 44:10"},{"k":"text","la":"Fíliæ regum in honóre tuo, ástitit regína a dextris tuis in vestítu deauráto, circúmdata varietáte. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Ascéndant ad te, Dómine, quas in beátæ Catharínæ solemnitáte offérimus, preces, et hóstia salutáris, virgíneo fragrans odóre."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 25:4-6"},{"k":"text","la":"Quinque prudéntes vírgines accepérunt óleum in vasis suis cum lampádibus: média autem nocte clamor factus est: Ecce, sponsus venit: exíte óbviam Christo Dómino. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Æternitátem nobis, Dómine, cónferat, qua pasti sumus, mensa cœléstis: quæ beátæ Catharínæ Vírginis vitam étiam áluit temporálem."},{"k":"macro","name":"Per Dominum"}]},"hr":{"98deced1a52f94b4":{"t":"Ps 44, 8, Ps 44, 2\n(Ps 44, 8) Ljubiš pravdu a mrziš nepravdu. Zato te je pomazao Bog, Bog tvoj, uljem radosti više nego drugarice tvoje. <i>Aleluja</i>, <i>aleluja</i>.\n(Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam djela svoja Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 44, 8) Ljubiš pravdu a mrziš nepravdu. Zato te je pomazao Bog, Bog tvoj, uljem radosti više nego drugarice tvoje. <i>Aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 44, 8). Ti ljubiš pravdu i mrziš nepravdu, zato te pomazao Gospodin Bog tvoj uljem radosti izabravši te od svih dru.garica tvojih, Aleluja, Aleluja (Ps. 44, 2). Iz mog srca Izvire divna pjesma: djela su moja namijenjena kralju! Slava Ocu. Ti ljubiš, <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"05334d8aebde1677":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da se mi koji slavimo rođendan za nebo blažene Katarine djevice tvoje i radujemo o godišnjoj svetkovini i okoristimo primjerom tolike kreposti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da se mi, koji slavimo rođeni dan bi.' Katarine, Tvoje djevice, poput spasonosne žrtve, koja odiše mirisom predujemo primjerom tolike kreipostl, po G. n.","knRef":"Kniewald 1942, str. 556–557 (snimka 279) (OCR)"},"2e242204d5c46dd6":{"t":"2 Kor 10, 17-18, 11, 1-2\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, tko se hvali neka se hvali u Gospodinu. Jer nije prokušan onaj koji se sam hvali, nego koga Bog hvali. O da biste malo podnosili moje bezumlje! Ali ipak podnesite me, jer revnujem za vas Božjom revnošću. Zaručio sam vas jednom čovjeku Kristu da vas preda nj izvedem kao čistu djevicu.","kn":"Čitanje poslanice bi. Pavla apostola Korinćanima (II, 10, 17-18. 11, 1-2). Braćo! Koji se hvali, neka se hvali u Gospodinu. Jer nije prokušan onaj, koji se sam preporučuje, nego koga preporučuje Bog. O da biste ipodnesld nešto malo moje ludosti! Ali ipak r po'dnesite me, jer revnujem za vas Božjim žarom. Zaručio sam vas jednomu mužu, da vas privedem Kristu kao čistu djevicu.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"a21f9f866c54e28b":{"t":"Ps 44, 15-16, Ps 44, 5\n<i>Aleluja</i>, <i>aleluja</i>.\nZa njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti. <i>Aleluja</i>.\nU svojoj veličanstvenoj ljepoti sretno pođi, napreduj i kraljuj. <i>Aleluja</i>.","kn":"Aleluja-, Aleluja (Pr. 44, 15, 16). Prate je djevice I i vode je kralju u radosti i veselju. Aleluja (Ps. 44, , 5). U svojoj veličanstvenoj ljepoti sretno pođi, pohitaj prama pobjedi i kraljuj! Aleluja. I, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 822–823 (snimka 412) (OCR)"},"04a5e5f3be261c56":{"t":"Mt 25, 1-13\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Kraljevstvo je nebesko kao deset djevica, koje uzeše svoje svjetiljke i iziđoše u susret zaručniku i zaručnici. Pet ih je bilo ludih, a pet mudrih. Pet ludih uzeše svjetiljke, a ne uzeše sa sobom ulja, a mudre sa svjetiljkama uzeše ulja u svojim posudama. Ali jer se zaručnik zabavio, sve zadrijemaše i zaspaše. A o ponoći nasta vika: Evo, ide zaručnik, iziđite mu u susret! Tada ustaše sve djevice i zapališe svoje svjetiljke. Lude tada reknu mudrima: Dajte nam od svoga ulja, jer se gase naše svjetiljke. Mudre odgovore: Da ne bi ponestalo nama i vama, idite radije do prodavača i kupite. Dok su išle kupovati, dođe zaručnik, i koje su bile spremne, uđu s njim na svadbu i zatvore se vrata. Napokon dođu i ostale djevice i reknu: Gospodine, Gospodine, otvori nam! On im odgovori: Zaista vam kažem: Ne poznam vas. Bdijte dakle, jer ne znate ni dana ni časa.","kn":"t Slijedi sv. evanđelje po Mateju (25, 1-13). U ono vrijeme reče Isus svojim učenicima ovu prispodobu: Kraljevstvo je nebesko kao deset djevica, koje uzeše svoje svjetiljke 1 iziđoše ususret zaručniku i zaručnici. Pet ih je bilo ludih, a pet mudrih. Pet ludih uzeše svjetiljke, a ne uzeše sa sobom ulja, a mudre sa svjetiljkama uzeše ulja u svojim posudama. Ali jer se zaručnik zabavio, sve zadrijemaše i zaspaše. A o ponoći nasta vika; Evo, ide zaručnik, iziđite mu ususret! Tada ustadoše sve djevice i zapališe svoje svjetUjke. Lude tada reknu mudrima: Dajte nam od svoga ulja, jer se gase naše svjetiljke. Mudre odgovore: Da ne bi ponestalo nama i vama, idite radije do prodavača i kupite. Dok su išle kupovati, dođe zaručnik, i koje'su bile spremne, uniđu s njim na svadbu i zatvore se vrata. Napokon dođu i ostale djevice i reknu: Gospodine, Gospodine, otvori nam! On im odgovori: Zaista vam kažem: Ne poznam vas. Bdijte, dakle, jer ne znate ni dana ni časa!","knRef":"Kniewald 1942, str. 826–827 (snimka 414) (OCR)"},"385bf2ecf149b949":{"t":"Ps 44, 10\nKraljevske kćeri dolaze ti ususret, Kraljica stoji uz desnu tvoju ogrnuta presjajnom zlatnom haljinom. <i>Aleluja</i>.","kn":"(Ps. 44, 16). Pratit će te kćeri kraljevske: z desne tvoje sama kraljica, ogrnuta presjajnom zlatnom haljinom, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 826–827 (snimka 414) (OCR)"},"1ba5b031ba065c6a":{"t":"Vinule se preda te. Gospodine, molitve koje ti prinosimo o svetkovini blažene Katarine i spasonosni dar, koji odiše djevičanskim mirisom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Vinule se preda Te. Gospodine, molitve, što ih prikazujemo o svetkovini bi. Katarine, Tvoje djecive, poput spasonosne žrtve, koja odiše mirisom djevičanetva, po G. n.","knRef":"Kniewald 1942, str. 556–557 (snimka 279) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"229a846c45bcb105":{"t":"Mt 25, 4 i 6\nPet je mudrih djevica uzelo ulje u svojim posudama zajedno sa svjetiljkama. A o ponoći začu se vika: Evo dolazi zaručnik, iziđite ususret Kristu Gospodinu. <i>Aleluja</i>.","kn":"(Mt. 25, 4, 6.) Pet je mudrih djevica uzelo ulje u posudama svojim sa svjetiljkama; a o ponoći nasta vika: Evo ide zaručnik, iziđite ususrte Kristu Gospodinu! <i>Aleluja</i>.","knRef":"Kniewald 1942, str. 826–827 (snimka 414) (OCR)"},"e6ceb769542553bb":{"t":"<i>Pomolimo se</i>.\nDonijela nam, Gospodine, vječni život nebeska gozba, što smo je blagovali koja je podržavala i vremeniti život blažene Katarine djevice.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Donijela nam, Gospodine, sveta gozba, koju smo blagovali, nebesku vječnost, jer je bi. Katairini uzdržavala i vremeniti život, po G. n.","knRef":"Kniewald 1942, str. 558–559 (snimka 280) (OCR)"}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}]}}});
